"use client";

import { Box, Button, FormControlLabel, Stack, Switch, Typography } from "@mui/material";
import { useThemeMode } from "@/components/ThemeModeProvider";
import dicConstant from "@/constants/Constant.json";

// Renders settings toggles including dark-mode integration.
export default function SettingsPanel() {
  // Functional responsibility:
  // - Render settings toggles, including theme-mode integration via context.
  // Inputs:
  // - Reads current mode/toggle handler from useThemeMode context.
  // Output:
  // - Settings controls and save button UI.
  // Failure behavior:
  // - If provider is missing, useThemeMode throws explicit context error.
  const { mode, toggleMode } = useThemeMode();

  return (
    <Stack spacing={3}>
      <Typography variant="body1" color="text.secondary">
        {dicConstant.settings.description}
      </Typography>
      <Stack spacing={1.25}>
        <Box sx={{ px: 1.5, py: 1, border: "1px solid", borderColor: "divider", borderRadius: 2 }}>
          <FormControlLabel
            control={<Switch checked={mode === "dark"} onChange={toggleMode} />}
            label={dicConstant.settings.darkMode}
          />
        </Box>
        <Box sx={{ px: 1.5, py: 1, border: "1px solid", borderColor: "divider", borderRadius: 2 }}>
          <FormControlLabel control={<Switch defaultChecked />} label={dicConstant.settings.emailNotifications} />
        </Box>
        <Box sx={{ px: 1.5, py: 1, border: "1px solid", borderColor: "divider", borderRadius: 2 }}>
          <FormControlLabel control={<Switch />} label={dicConstant.settings.attendanceSummary} />
        </Box>
      </Stack>
      <Button variant="contained" sx={{ alignSelf: "flex-start" }}>
        {dicConstant.settings.saveButton}
      </Button>
    </Stack>
  );
}
